import threading

def reproduce(connect, service) -> str | None:
    acct = 1
    initial = 1000
    amount = 1000
    N = 32
    ROUNDS = 8

    for rnd in range(ROUNDS):
        with connect() as conn:
            conn.execute("UPDATE accounts SET balance = %s WHERE id = %s", (initial, acct))

        # pre-open one connection per thread to remove setup jitter
        conns = [connect() for _ in range(N)]
        barrier = threading.Barrier(N)

        def worker(idx):
            try:
                barrier.wait(timeout=10)
            except Exception:
                return
            try:
                try:
                    service.withdraw(conns[idx], acct, amount)
                except service.InsufficientFunds:
                    pass
                except Exception:
                    pass
            except Exception:
                pass

        threads = [threading.Thread(target=worker, args=(i,)) for i in range(N)]
        for t in threads:
            t.start()
        for t in threads:
            t.join(timeout=30)
        for c in conns:
            try:
                c.close()
            except Exception:
                pass

        with connect() as conn:
            row = conn.execute("SELECT balance FROM accounts WHERE id = %s", (acct,)).fetchone()
            final = row[0] if row else None
        if final is not None and final < 0:
            return f"overdraft violation: account {acct} balance {final} < 0 after {N} concurrent withdraws of {amount} from {initial} (round {rnd+1})"
    return None

